effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }

// LAYER -> SCREEN. The bands are cut from layer coordinates and every read
// comes back through the layer transform.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }
vec3 strL(vec2 lp){ vec4 s = fetchL(lp); return s.rgb / max(s.a, 1e-4); }

float h21(vec2 p){ return fract(sin(dot(p + seed * 1.71, vec2(127.1, 311.7))) * 43758.5453123); }

vec2 edgeFix(vec2 lp){
if (edgeMode <= 0) return clamp(lp, 0.0, 1.0);
if (edgeMode <= 1){
vec2 m = mod(lp, vec2(2.0, 2.0));
return abs(m - vec2(1.0, 1.0)) * -1.0 + vec2(1.0);
}
return fract(lp);
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float al = max(src.a, 1.0e-4);
vec3 sc = src.rgb / al;

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  q   = vec2((lp.x - 0.5) * asp, lp.y - 0.5);

float ra   = radians(direction);
vec2  ax   = vec2(cos(ra), sin(ra));
vec2  perp = vec2(-ax.y, ax.x);

float n  = max(slices, 2.0);
float s  = dot(q, ax);
float sf = (s + 1.0) * 0.5 * n;
float si = floor(sf);
float sfr = sf - si;

// Feathering the band INDEX rather than blending two separate results: the
// offset is a continuous function of the index, so a fractional index gives a
// smooth cross-fade for free.
float fe = clamp(feather, 0.0, 0.95);
float edge = smoothstep(1.0 - max(fe, 0.001), 1.0, sfr);
float sif  = mix(si, si + 1.0, edge * fe);
float bc   = (sif + 0.5) / n * 2.0 - 1.0;

float t   = acTime * speed;
float acc = pow(clamp((sif + 0.5) / n, 0.0, 1.0), max(curve, 0.05));
float off = acc * offset * 2.0
          + (h21(vec2(floor(si), floor(t * 3.0))) - 0.5) * stagger * 0.25
          + t * 0.12;

// ---- construction -------------------------------------------------------
vec2 qd = q;
if (sliceMode <= 0){
qd = q + perp * off;
} else if (sliceMode <= 1){
// Replace the slice coordinate with this band's own centre, so the picture is
// sampled from one line and smeared across the band.
qd = q + ax * (bc - s);
} else if (sliceMode <= 2){
// Reflect about the band centre - twice the displacement, opposite sign.
qd = q + ax * ((bc - s) * 2.0);
} else if (sliceMode <= 3){
// Polar version: the bands are angular sectors and the offset is radial.
float ang = atan(q.y, q.x);
float af  = (ang / 6.2831853 + 0.5) * n;
float ai  = floor(af);
float accR = pow(clamp((ai + 0.5) / n, 0.0, 1.0), max(curve, 0.05));
float offR = accR * offset * 2.0
           + (h21(vec2(ai, floor(t * 3.0)) + 5.0) - 0.5) * stagger * 0.25
           + t * 0.12;
qd = q * (1.0 + offR);
} else if (sliceMode <= 4){
// Scale each band around its own centre.
float sc2 = 1.0 + (s - bc) * bandScale;
qd = q + ax * (s * (sc2 - 1.0));
} else {
// Freeze Column - every band reads from the first one.
float bc0 = 0.5 / n * 2.0 - 1.0;
qd = q + ax * (bc0 - s);
}

vec2 dpos = vec2(qd.x / max(asp, 1.0e-3), qd.y) + vec2(0.5);

vec3 c = strL(edgeFix(dpos));
if (blur > 0.001){
// A small perpendicular average inside the band: takes the hard edge off the
// sampling without bleeding across band boundaries.
float bw = blur * 0.014;
c += strL(edgeFix(dpos + perp * bw));
c += strL(edgeFix(dpos - perp * bw));
c /= 3.0;
}

c = sat3v(c);
vec3  col = mix(sc, c, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
